sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var gr = new GlideRecord('x_1439619_business_business_card_calculator');
    gr.query();
    if(gr.next()) {
        if(gr.limit_type == 'yearly') {
            var gdt = new GlideDateTime();
            var currentMonth = gdt.getMonthLocalTime();
            var monthLeft = 12 - currentMonth;

            var perMonth = gr.limit / 12;
            var totalLimit = perMonth * monthLeft;

            // ตรวจสอบว่าพนักงานขอนามบัตรเกิน limit แล้วหรือยัง
            var requestCount = new GlideAggregate('x_1439619_business_business_card_request');
            requestCount.addAggregate('SUM', 'quantity');
            requestCount.addQuery('employee', current.sys_id);
            requestCount.query();

            if (requestCount.next()) {
                var totalRequested = requestCount.getAggregate('SUM', 'quantity');
                if (totalRequested >= gr.limit) {
                    gs.addErrorMessage('คุณได้ขอนามบัตรครบจำนวนที่กำหนดแล้วในปีนี้');
                    return;
                }
            }

            var BusinessCardBucket = new GlideRecord('x_1439619_business_business_card_bucket');
            BusinessCardBucket.initialize();
            BusinessCardBucket.limit = totalLimit;
            BusinessCardBucket.employee = current.sys_id;
            BusinessCardBucket.insert();
        }
    }

})(current, previous);
